    // Use this instead of MailMessage.Body so the CID images are included in the email.
    public static AlternateView CreateAlternateView(dynamic data)
    {
        var html = GetHtml(data);
        var view = AlternateView.CreateAlternateViewFromString(html, System.Text.Encoding.UTF8, MediaTypeNames.Text.Html);
        AddInlineImage(view, HeaderImageBase64, "HeaderImage", "image/png");
        AddInlineImage(view, AxaMandiriLogoBase64, "AxaMandiriLogo", "image/png");
        return view;
    }

    private static void AddInlineImage(AlternateView view, string base64, string contentId, string mediaType)
    {
        var bytes = Convert.FromBase64String(base64);
        var stream = new MemoryStream(bytes);
        var resource = new LinkedResource(stream, mediaType)
        {
            ContentId = contentId,
            TransferEncoding = TransferEncoding.Base64
        };
        view.LinkedResources.Add(resource);
    }
}
